сход."],"version":1,"mealTypes":["breakfast","lunch","dinner"],"cuisine":"home"},{"id":"vegetable-salad","title":"Салат из огурцов и помидоров","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"cucumber","quantity":{"value":150,"unit":"g"}},{"ingredientId":"tomato","quantity":{"value":150,"unit":"g"}},{"ingredientId":"oil","quantity":{"value":5,"unit":"ml"}}],"steps":["Подготовьте и отмерьте продукты.","Нарежьте овощи, смешайте с маслом.","Перед списанием укажите фактический расход."],"version":1,"mealTypes":["lunch","dinner"],"cuisine":"home"},{"id":"egg-cucumber","title":"Салат с яйцом и огурцом","basePortions":1,"allowedModes":["standard"],"variantOf":"cheese-cucumber","ingredients":[{"ingredientId":"egg","quantity":{"value":2,"unit":"pcs"}},{"ingredientId":"cucumber","quantity":{"value":150,"unit":"g"}}],"steps":["Сварите яйца, остудите и очистите.","Нарежьте яйца и огурец, смешайте.","Перед списанием укажите фактический расход."],"version":1,"mealTypes":["breakfast","lunch","dinner"],"cuisine":"home"},{"id":"cheese-omelette","title":"Омлет с сыром","mealTypes":["breakfast"],"cuisine":"home","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"egg","quantity":{"value":2,"unit":"pcs"}},{"ingredientId":"cheese","quantity":{"value":30,"unit":"g"}},{"ingredientId":"butter","quantity":{"value":5,"unit":"g"}}],"steps":["Взбейте яйца, натрите сыр.","Растопите сливочное масло на сковороде, вылейте яйца и посыпьте сыром.","Доведите омлет до готовности."],"version":1},{"id":"tamagoyaki-rice","title":"Тамагояки с рисом","mealTypes":["breakfast"],"cuisine":"japanese","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"short-grain-rice","quantity":{"value":60,"unit":"g"}},{"ingredientId":"egg","quantity":{"value":2,"unit":"pcs"}},{"ingredientId":"sugar","quantity":{"value":5,"unit":"g"}},{"ingredientId":"salt","quantity":{"value":1,"unit":"g"}},{"ingredientId":"neutral-oil","quantity":{"value":5,"unit":"ml"}}],"steps":["Сварите отмеренный сухой рис в воде по инструкции на упаковке.","Взбейте яйца с сахаром и солью. Смажьте сковороду маслом.","Жарьте яичную смесь тонкими слоями, сворачивая готовый слой на следующий. Полностью приготовьте омлет, нарежьте и подайте с рисом."],"version":1},{"id":"salmon-onigiri","title":"Онигири с лососем и нори","mealTypes":["lunch"],"cuisine":"japanese","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"short-grain-rice","quantity":{"value":60,"unit":"g"}},{"ingredientId":"salmon","quantity":{"value":75,"unit":"g"}},{"ingredientId":"nori","quantity":{"value":2,"unit":"g"}},{"ingredientId":"salt","quantity":{"value":1,"unit":"g"}}],"steps":["Сварите отмеренный сухой рис в воде по инструкции на упаковке.","Приготовьте лосось до полной готовности и разберите вилкой, убрав кости.","Посолите рис, сформируйте рисовые шарики с начинкой из лосося и оберните полосками нори."],"version":1},{"id":"shiozake-rice","title":"Лосось с рисом в стиле сиодзакэ","mealTypes":["dinner"],"cuisine":"japanese","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"short-grain-rice","quantity":{"value":60,"unit":"g"}},{"ingredientId":"salmon","quantity":{"value":120,"unit":"g"}},{"ingredientId":"salt","quantity":{"value":2,"unit":"g"}}],"steps":["Сварите отмеренный сухой рис в воде по инструкции на упаковке.","Посолите филе лосося и запеките до полной готовности.","Проверьте, что в филе нет костей, и подайте с рисом."],"version":1},{"id":"potato-cucumber-salad","title":"Картофельный салат с огурцом","mealTypes":["lunch"],"cuisine":"home","basePortions":1,"allowedModes":["standard"],"ingredients":[{"ingredientId":"potato","quantity":{"value":200,"unit":"g"}},{"ingredientId":"cucumber","quantity":{"value":100,"unit":"g"}},{"ingredientId":"herbs","quantity":{"value":5,"unit":"g"}},{"ingredientId":"oil","quantity":{"value":10,"unit":"ml"}}],"steps":["Отварите картофель в воде до готовности и остудите.","Нарежьте картофель и огурец, измельчите зелень.","Перемешайте и заправьте отмеренным маслом."],"version":1}],"version":2}$data$::jsonb;
